<?php

declare(strict_types=1);

namespace BrotherTours\OperationsApi\Connections;

use BrotherTours\OperationsApi\Auth\Csrf;
use WP_REST_Request;

use function BrotherTours\OperationsApi\error;
use function BrotherTours\OperationsApi\response;
use function BrotherTours\OperationsApi\table_exists;

final class ConnectionsController {
	private const EVENTS=array('inquiry.created','booking.deposit_link','booking.deposit_paid','booking.confirmed','booking.balance_link','booking.balance_paid');
	public function register():void{add_action('rest_api_init',array($this,'routes'));}
	public function routes():void{
		$read=static fn(WP_REST_Request $r)=>Csrf::authorize($r,'bt_manage_operations',false);$admin_write=static fn(WP_REST_Request $r)=>Csrf::authorize($r,'manage_options',true);
		register_rest_route(BTOA_NAMESPACE,'/connections',array(array('methods'=>'GET','callback'=>array($this,'list'),'permission_callback'=>$read),array('methods'=>'POST','callback'=>array($this,'create'),'permission_callback'=>$admin_write)));
		register_rest_route(BTOA_NAMESPACE,'/connections/(?P<id>\d+)',array(array('methods'=>'PATCH','callback'=>array($this,'update'),'permission_callback'=>$admin_write),array('methods'=>'DELETE','callback'=>array($this,'delete'),'permission_callback'=>$admin_write)));
		register_rest_route(BTOA_NAMESPACE,'/connections/logs',array('methods'=>'GET','callback'=>array($this,'logs'),'permission_callback'=>$read));
	}
	public function list(){global $wpdb;$table=$wpdb->prefix.'wpistic_connections';if(!table_exists($table))return error('bt_ops_connections_unavailable',__('Connections table is unavailable.','brother-tours-operations-api'),503);$rows=$wpdb->get_results("SELECT id,name,type,target_url,events,enabled,created_at,CASE WHEN secret IS NOT NULL AND secret<>'' THEN 1 ELSE 0 END has_secret FROM {$table} ORDER BY id DESC",ARRAY_A);return response(array('items'=>array_map(array($this,'format'),(array)$rows),'supportedEvents'=>self::EVENTS));}
	public function create(WP_REST_Request $r){global $wpdb;$table=$wpdb->prefix.'wpistic_connections';if(!table_exists($table))return error('bt_ops_connections_unavailable',__('Connections table is unavailable.','brother-tours-operations-api'),503);$p=$this->params($r);$valid=$this->validate($p,true);if(is_wp_error($valid))return $valid;$ok=$wpdb->insert($table,array('name'=>$valid['name'],'type'=>'webhook','target_url'=>$valid['targetUrl'],'secret'=>$valid['secret'],'events'=>wp_json_encode($valid['events']),'enabled'=>$valid['enabled']?1:0,'created_at'=>current_time('mysql',true)),array('%s','%s','%s','%s','%s','%d','%s'));if(!$ok)return error('bt_ops_connection_create_failed',__('Connection could not be created.','brother-tours-operations-api'),500);$id=(int)$wpdb->insert_id;return response($this->get_row($id),201);}
	public function update(WP_REST_Request $r){global $wpdb;$id=(int)$r['id'];$existing=$this->get_row($id,true);if(!$existing)return error('bt_ops_connection_not_found',__('Connection not found.','brother-tours-operations-api'),404);$p=$this->params($r);$merged=array('name'=>$p['name']??$existing['name'],'targetUrl'=>$p['targetUrl']??$existing['target_url'],'events'=>$p['events']??json_decode((string)$existing['events'],true),'enabled'=>array_key_exists('enabled',$p)?$p['enabled']:(bool)$existing['enabled'],'secret'=>array_key_exists('secret',$p)?$p['secret']:'');$valid=$this->validate($merged,false);if(is_wp_error($valid))return $valid;$data=array('name'=>$valid['name'],'target_url'=>$valid['targetUrl'],'events'=>wp_json_encode($valid['events']),'enabled'=>$valid['enabled']?1:0);$formats=array('%s','%s','%s','%d');if(array_key_exists('secret',$p)&&''!==(string)$p['secret']){$data['secret']=$valid['secret'];$formats[]='%s';}$ok=$wpdb->update($wpdb->prefix.'wpistic_connections',$data,array('id'=>$id),$formats,array('%d'));if(false===$ok)return error('bt_ops_connection_update_failed',__('Connection could not be updated.','brother-tours-operations-api'),500);return response($this->get_row($id));}
	public function delete(WP_REST_Request $r){global $wpdb;$id=(int)$r['id'];if(!$this->get_row($id,true))return error('bt_ops_connection_not_found',__('Connection not found.','brother-tours-operations-api'),404);$ok=$wpdb->delete($wpdb->prefix.'wpistic_connections',array('id'=>$id),array('%d'));return false!==$ok?response(array('id'=>$id,'deleted'=>true)):error('bt_ops_connection_delete_failed',__('Connection could not be deleted.','brother-tours-operations-api'),500);}
	public function logs(WP_REST_Request $r){global $wpdb;$table=$wpdb->prefix.'wpistic_connection_log';if(!table_exists($table))return error('bt_ops_connection_logs_unavailable',__('Connection log is unavailable.','brother-tours-operations-api'),503);$page=max(1,(int)$r->get_param('page'));$per=min(100,max(1,(int)($r->get_param('per_page')?:50)));$where=array('1=1');$args=array();$id=absint($r->get_param('connection_id'));if($id){$where[]='connection_id=%d';$args[]=$id;}$event=sanitize_text_field((string)$r->get_param('event'));if($event!==''){$where[]='event=%s';$args[]=$event;}$status=sanitize_key((string)$r->get_param('status'));if('failed'===$status)$where[]='(status_code < 200 OR status_code >= 300)';elseif('success'===$status)$where[]='(status_code >= 200 AND status_code < 300)';$sql_where=implode(' AND ',$where);$count="SELECT COUNT(*) FROM {$table} WHERE {$sql_where}";$total=(int)$wpdb->get_var($args?$wpdb->prepare($count,$args):$count);$query="SELECT * FROM {$table} WHERE {$sql_where} ORDER BY id DESC LIMIT %d OFFSET %d";$rows=$wpdb->get_results($wpdb->prepare($query,array_merge($args,array($per,($page-1)*$per))),ARRAY_A);$items=array_map(static fn($x)=>array('id'=>(int)$x['id'],'connectionId'=>(int)$x['connection_id'],'event'=>(string)$x['event'],'statusCode'=>(int)$x['status_code'],'success'=>(int)$x['status_code']>=200&&(int)$x['status_code']<300,'response'=>wp_strip_all_tags(wp_trim_words((string)$x['response'],100,'…')),'attempts'=>(int)$x['attempts'],'createdAt'=>(string)$x['created_at']),(array)$rows);return response(array('items'=>$items,'total'=>$total,'page'=>$page,'perPage'=>$per,'totalPages'=>(int)ceil($total/$per)));}
	private function validate(array $p,bool $secret_required){$name=sanitize_text_field((string)($p['name']??''));$url=esc_url_raw((string)($p['targetUrl']??''));$secret=sanitize_text_field((string)($p['secret']??''));$events=array_values(array_intersect(self::EVENTS,array_map('sanitize_text_field',(array)($p['events']??array()))));if($name==='')return error('bt_ops_connection_name_required',__('Connection name is required.','brother-tours-operations-api'),422);if(!$url||!wp_http_validate_url($url))return error('bt_ops_connection_url_invalid',__('A valid public webhook URL is required.','brother-tours-operations-api'),422);$scheme=(string)wp_parse_url($url,PHP_URL_SCHEME);if('https'!==strtolower($scheme)&&!(defined('WP_DEBUG')&&WP_DEBUG))return error('bt_ops_connection_https_required',__('Webhook URLs must use HTTPS.','brother-tours-operations-api'),422);if($secret_required&&strlen($secret)<16)return error('bt_ops_connection_secret_required',__('Use a signing secret of at least 16 characters.','brother-tours-operations-api'),422);if(!$events)return error('bt_ops_connection_events_required',__('Select at least one supported event.','brother-tours-operations-api'),422);return array('name'=>$name,'targetUrl'=>$url,'secret'=>$secret,'events'=>$events,'enabled'=>filter_var($p['enabled']??true,FILTER_VALIDATE_BOOLEAN));}
	private function format(array $r):array{return array('id'=>(int)$r['id'],'name'=>(string)$r['name'],'type'=>(string)$r['type'],'targetUrl'=>(string)$r['target_url'],'events'=>is_array(json_decode((string)$r['events'],true))?json_decode((string)$r['events'],true):array(),'enabled'=>(bool)$r['enabled'],'hasSecret'=>!empty($r['has_secret'])||!empty($r['secret']),'createdAt'=>(string)$r['created_at']);}
	private function get_row(int $id,bool $raw=false){global $wpdb;$table=$wpdb->prefix.'wpistic_connections';if(!table_exists($table))return null;$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id=%d",$id),ARRAY_A);if(!$row)return null;return $raw?$row:$this->format($row);}private function params(WP_REST_Request $r):array{$j=$r->get_json_params();return is_array($j)?$j:$r->get_params();}
}
